param([Parameter(Mandatory = $true)][ValidateSet("data-a", "daily", "model", "statements", "statements-refresh", "rl", "turnover", "exits", "execution", "blends", "rl-sleeves", "model-60", "t0hunt", "ai-researcher", "news-events", "lowdd", "largecap", "largecap2", "evidence", "scan", "scan4", "robots", "resume4", "robot2", "wide4", "consensus", "trials", "leakcheck", "devconsensus", "modelf", "costswitch", "rawv2", "techmodel", "hypotheses", "minhold", "engine13", "engine131", "dividends", "engine140", "t0scan5", "timefactors", "factormom", "audit", "robot20", "shortdata", "shortfactors", "alerts", "robot21", "rebuild141", "lendingdata", "lendingfactors", "rebuild142", "corporate", "issuance", "dealermodel", "robot30", "robot40", "rebuild143", "dealer2", "deep1", "robot41", "reductions", "robot31", "rebuild150", "worst", "dlrisk", "riskrules", "dealer3", "scan4gpu", "timing", "rolling", "rolling-holdout", "forward-rolling", "deep2a", "deep2b", "deep2cost", "deep2leak", "deep2risk", "deep2cluster", "deep2r3", "deep2scan", "deep2large", "exit2", "coresat", "deep3", "deep2wide", "robustness", "rolling-regrade", "rolling-blends", "spread", "deep2timing", "trim", "blendscan", "insiderdata", "buybackdata", "disclosurestudy", "factorcorr", "modelh", "deep2neutral", "deep24", "deep2top10", "costall", "pledgestudy", "threefam", "industry", "techdeep", "robot32", "robot33", "meta1", "winner", "deep26", "modelgm", "rolesplit", "robot34", "holding", "holding2_a", "holding2_b", "holding3", "holding4_a", "holding4_b", "top10blend", "bigscan", "bigscan2", "listupdate", "robustfront", "exec_a", "exec_b", "llmreplay", "monthmodels", "next10blend", "llmtrader", "scancalm", "factors-recent", "archive", "seed", "factors", "finmind", "finmind-paid", "finmind-paid-b", "finmind-paid-c", "paid-factors", "newdata", "intraday", "limitscheck", "finmind-paid-c2", "newdata-now", "finmind-paid-rest", "holders2", "holders3", "liveflow", "modeli", "monthfill", "deep27", "modelj", "jdeep", "split", "split_a", "split_b", "splitblend", "splitblends", "splitblends_a", "splitblends_b", "bigscan3", "fmdaily_a", "fmdaily_b", "openfeas", "opentight", "govbank", "engine160", "veto2", "knowledge", "veto3_a", "veto3_b", "vetoblends_a", "vetoblends_b", "veto4", "veto5", "forwardrepair", "veto6", "blendroll", "bigscanroll", "govbank2", "branches", "robot35", "paidveto", "robot35s", "deephalf", "blendsteady", "stress", "protect", "bearguard_a", "bearguard_b", "bearguardpost", "bearguard", "bearguard3", "bearguard4", "bearguard5", "blendguard", "forwardfix", "forwardaudit", "forwardwhy", "entryonly", "leakfix", "fullscan", "modelk", "leakfixend", "spreadwatch", "halftwins_a", "halftwins_b", "halftwinsend", "gate2020", "band", "issues", "bandsells", "reproduce", "reproducecheck", "bear6", "modell", "stalefix", "rl4", "bear7", "modelm", "bear8", "blendrecent", "fwdminutes", "rebuild160_a", "rebuild160_b", "rebuild160end", "forwardaudit2")][string]$Name)
# Start a long research run outside the assistant's process tree (2026-10-06): at 02:36 a Claude desktop
# update closed the pipeline that had been started with Start-Process from the assistant's shell, and the
# FinMind download with it, half-way. Win32_Process.Create makes the new process a child of the WMI
# service instead, so it keeps running whatever happens to the session that started it. No scheduled
# task or other setting is created. Progress: the website's 研究 › 執行中的程式; output: instance\research\logs.
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$script = Join-Path $root "scripts\research-pipeline.ps1"
# 2026-10-20 23:0x (使用者：誰叫你開一大堆 cmd，也沒講在幹嘛、也沒有 log): with Windows Terminal as the default terminal
# (Windows 11, no DelegationConsole set) -WindowStyle Hidden is ignored and every run opened a blank window; the owner
# closed them and the runs stopped. conhost --headless gives the run a console without any window, and its children
# (Start-Process -NoNewWindow) share it. Each run writes <name>-<stamp>-pipeline.log: every step, when it began and ended.
$command = "conhost.exe --headless powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"$script`" -Name $Name"
$startup = New-CimInstance -ClassName Win32_ProcessStartup -ClientOnly -Property @{ ShowWindow = [uint16]0 }
$result = Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{
    CommandLine = $command; CurrentDirectory = $root; ProcessStartupInformation = $startup }
if ($result.ReturnValue -ne 0) {
    throw "Win32_Process.Create failed with $($result.ReturnValue)"
}
Write-Output "Started research pipeline '$Name' (PID $($result.ProcessId), no window); progress: website Research > Jobs; steps: instance\research\logs\$Name-*-pipeline.log"
